changeSet.sql:
ALTER TABLE nexus.gc_audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.gc_audit FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.gc_audit
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

changeSet.rollback:
DROP POLICY IF EXISTS tenant_isolation ON nexus.gc_audit;
ALTER TABLE nexus.gc_audit NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.gc_audit DISABLE ROW LEVEL SECURITY;
